(() => {
  const G = globalThis.GB;
  G.Observer = class {
    constructor(app) {
      this.app = app; this.queue = new Set(); this.timer = null; this.walker = null;
      this.observer = new MutationObserver(records => {
        for (const record of records) {
          const target = record.target.nodeType === 1 ? record.target : record.target.parentElement;
          if (!target || target.closest('[data-gb-ui]')) continue;
          // A mutation generated by the extension is not observed (attributes are whitelisted).
          if (record.type === 'childList') {
            for (const node of record.addedNodes) if (node.nodeType === 1 && !node.matches('[data-gb-ui]')) this.enqueue(node);
          }
          if (target !== document.body && target !== document.documentElement) this.enqueue(target);
        }
        this.schedule();
      });
    }
    enqueue(element) {
      if (element?.closest?.('[data-gb-ui]')) return;
      if (this.queue.size < 1500) this.queue.add(element);
    }
    start() {
      this.observer.observe(document.documentElement, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['title', 'alt', 'aria-label', 'href', 'src', 'poster', 'content'] });
      this.scan();
    }
    scan() { this.walker = document.createTreeWalker(document.body || document.documentElement, NodeFilter.SHOW_ELEMENT); this.schedule(); }
    schedule() { if (!this.timer) this.timer = setTimeout(() => this.flush(), 60); }
    flush() {
      this.timer = null;
      if (!this.app.isActive()) { this.queue.clear(); this.walker = null; return; }
      this.app.page.inspect();
      let processed = 0;
      while (processed < 180) {
        let element;
        if (this.queue.size) { element = this.queue.values().next().value; this.queue.delete(element); }
        else if (this.walker) { element = this.walker.nextNode(); if (!element) this.walker = null; }
        if (!element) break;
        processed++;
        if (!element.isConnected || element.closest(G.SKIP)) continue;
        this.app.inspect(element);
        // Incremental traversal of a newly inserted subtree; original full scans already traverse children.
        if (element.childElementCount && !this.walker) for (const child of element.children) this.enqueue(child);
      }
      this.app.page.inspect(); this.app.blocker.prune(); this.app.video.prune();
      if (this.queue.size || this.walker) this.schedule();
    }
  };
})();
